  ('physics-board-barishal-2023-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p71', 'একটি স্কেলের সাহায্যে সর্বনিম্ন 1mm মাপা যায়। যদি কোনো বস্তুর দৈর্ঘ্য 1mm হয় তবে পরিমাপের শতকরা আপেক্ষিক ত্রুটি কত হবে?', 'mcq', '{"ক":"0.5%","খ":"5%","গ":"100%","ঘ":"50%"}'::jsonb, 'গ', 1, false, 'physics-board-barishal-2023-mcq', false, 'board-mcq', null, null, 'barishal', 2023, true),
