  ('physics-board-barishal-2023-mcq-022', 'class9-physics-bn-guide', 'satt-physics-board.pdf p73', 'উদ্দীপকে-- i. শক্তির নিত্যতার সূত্রটি প্রযোজ্য ii. মোটরটির কর্মদক্ষতা 62.5% iii. অপচয়কৃ ত শক্তি 150J নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"i ও ii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-barishal-2023-mcq', false, 'board-mcq', null, 'একটি বৈদ্যুতিক মোটরের সাহায্যে 50N ওজনের একটি বস্তুকে ভূ -পৃষ্ঠ থেকে 5m উপরে উঠাতে 400J শক্তি সরবরাহ করতে হয়।', 'barishal', 2023, true),
