  ('physics-board-barishal-2024-mcq-006', 'class9-physics-bn-guide', 'satt-physics-board.pdf p8', 'বজ্রপাতের সময় চার্জ- i. বিশাল পরিমাণে পৃথিবীতে নেমে আসে ii. বাতাসের ভিতর দিয়ে যাওয়ার সময় তাকে আয়নিত করে iii. বাতাসের তাপমাত্রা বৃদ্ধি করে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-barishal-2024-mcq', false, 'board-mcq', null, null, 'barishal', 2024, true),
