  ('physics-board-barishal-2024-mcq-013', 'class9-physics-bn-guide', 'satt-physics-board.pdf p8', '10°C তাপমাত্রায় একটি দণ্ডের দৈর্ঘ্য 5m. 110°C তাপমাত্রায় দণ্ডটির দৈর্ঘ্য 5.0167m। এর দৈর্ঘ্য প্রসারণ সহগ কত?', 'mcq', '{"ক":"29940 K −1","খ":"0. 33 K −1","গ":"0. 000835 K −1","ঘ":"0. 0000334 K −1"}'::jsonb, 'ঘ', 1, false, 'physics-board-barishal-2024-mcq', false, 'board-mcq', null, null, 'barishal', 2024, true),
  ('physics-board-barishal-2024-mcq-014', 'class9-physics-bn-guide', 'satt-physics-board.pdf p8', 'একটি ট্রান্সফর্মারের প্রাইমারি কয়েলের প্যাঁচসংখ্যা 100. সেকেন্ডারি কয়েলের প্যাঁচসংখ্যা 1000, প্রাইমারি কয়েল দিয়ে 12V DC দেওয়া হলে, সেকেন্ডারি কয়েলে ভোল্টেজ কত?', 'mcq', '{"ক":"0","খ":"10","গ":"100","ঘ":"120"}'::jsonb, 'ক', 1, false, 'physics-board-barishal-2024-mcq', false, 'board-mcq', null, null, 'barishal', 2024, true),
