  ('physics-board-barishal-2024-mcq-017', 'class9-physics-bn-guide', 'satt-physics-board.pdf p9', 'কোনো পরিবাহীর দুই প্রান্তের বিভব পার্থক্য 120V এবং তড়িৎ প্রবাহমাত্রা 10A হলে এর রোধ কত?', 'mcq', '{"ক":"1200 Ω","খ":"12 Ω","গ":"0. 12 Ω","ঘ":"0. 1 Ω"}'::jsonb, 'খ', 1, false, 'physics-board-barishal-2024-mcq', false, 'board-mcq', null, null, 'barishal', 2024, true),
