  ('physics-board-barishal-2024-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p10', 'চিত্রের আলোকে শব্দের প্রতিধ্বনি- i. C বিন্দু থেকে শোনা যাবে না ii. B বিন্দু থেকে শোনা যাবে iii. A বিন্দুতে শুনতে 0.117 s সময় লাগে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-barishal-2024-mcq', false, 'board-mcq', null, null, 'barishal', 2024, true),
