  ('physics-board-chattogram-2021-mcq-004', 'class9-physics-bn-guide', 'satt-physics-board.pdf p111', 'স্থির অবস্থান থেকে সমত্বরণে বস্তুর যে কোনো সময়ের বেগ বস্তুর অতিক্রান্ত দূরত্বের—', 'mcq', '{"ক":"সমানুপাতিক","খ":"বর্গের সমানুপাতিক","গ":"বর্গের ব্যস্তানুপাতিক","ঘ":"বর্গের সমানুপাতিক"}'::jsonb, 'ঘ', 1, false, 'physics-board-chattogram-2021-mcq', false, 'board-mcq', null, null, 'chattogram', 2021, true),
