  ('physics-board-chattogram-2021-mcq-018', 'class9-physics-bn-guide', 'satt-physics-board.pdf p113', 'সমতল দর্পণে সৃষ্ট প্রতিবিম্বের বৈশিষ্ট্য— i. বিম্ব অবাস্তব ও সোজা ii. বিম্ব অবাস্তব ও সমান দৈর্ঘ্যের iii. দর্পণ থেকে বস্তুর দূরত্ব যত, দর্পণ থেকে বিম্বের দূরত্ব তার অর্ধেক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"ii ও iii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'physics-board-chattogram-2021-mcq', false, 'board-mcq', null, null, 'chattogram', 2021, true),
