  ('physics-board-cumilla-2019-mcq-007', 'class9-physics-bn-guide', 'satt-physics-board.pdf p193', '20 cm বক্তৃ তার ব্যাসার্ধবিশিষ্ট একটি অবতল দর্পণ থেকে 20 cm দূরে একটি বস্তু রাখা আছে। প্রতিবিম্বের দূরত্ব কত?', 'mcq', '{"ক":"","খ":"0.05 cm","গ":"20 cm","ঘ":"30 cm"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', 'অপশন চিহ্ন পাওয়া যায়নি: ক (ছাপায় নেই বা চিত্র আকারে); ক অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p193', '+ 4 C 3 + 6 C মানের দুটি চার্জ পরস্পর থেকে 10 cm দূরে স্থাপন করা হলো। চার্জ দুটি একটি পরিবাহী তার দ্বারা যুক্ত করে পুনরায় তারটি সরিয়ে নেওয়া হলো। বর্তমানে এদের মধ্যে ক্রিয়াশীল বলের মান কত?', 'mcq', '{"ক":"2. 16 × 10 N 9","খ":"2. 25 × 10 N 9","গ":"2. 16 × 10 11 N","ঘ":"2. 25 × 10 13 N"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p193', 'কোনটির উপর তরলের বাষ্পায়ন নির্ভর করে?', 'mcq', '{"ক":"ঘনত্ব","খ":"উচ্চতা","গ":"আয়তন","ঘ":"প্রকৃ তি"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-010', 'class9-physics-bn-guide', 'satt-physics-board.pdf p193', 'যদি দৈর্ঘ্য প্রসারণ সহগ, ক্ষেত্র প্রসারণ সহগ এবং আয়তন প্রসারণ সহগ যথাক্রমে α, β ও γ হয় তাহলে- i. α β = 1 2 ii. β γ = 2 3 iii. γ α = 3 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-011', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'একটি P টাইপের অর্ধ-পরিবাহী তৈরি করতে বিশুদ্ধ সিলিকনের সাথে কোন মৌলটি যোগ করতে হয়?', 'mcq', '{"ক":"ফসফরাস","খ":"কার্বন","গ":"অ্যান্টিমনি","ঘ":"বোরন"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'B রাশির সাথে A রাশির পরিবর্তন দেখানো হয়েছে, যা একটি কণার সরল তৈরিখক গতির ক্ষেত্রে- i. B রাশিটি সময় নির্দেশ করে ii. A রাশিটি দূরত্ব নির্দেশ করে, যদি কণাটির বেগ সূষম হয় iii. A রাশিটি বেগ নির্দেশ করে যদি কণাটি সমত্বরণে গতিশীল হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-013', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'একটি আরোহী ট্রান্সফরমারের ক্ষেত্রে কোনটি সঠিক?', 'mcq', '{"ক":"ভোল্টেজ বাড়ে","খ":"তড়িৎ প্রবাহ বাড়ে","গ":"তড়িৎ শক্তি কমে","ঘ":"তড়িৎ ক্ষমতা বাড়ে"}'::jsonb, 'ক', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-014', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'আল্ট্রাসনোগ্রাফিতে কোন কম্পাঙ্কের শব্দ ব্যবহার করা হয়?', 'mcq', '{"ক":"1-10 Hz","খ":"I-10 kHz","গ":"I - 10 MHz","ঘ":"I - 10 GHz"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-015', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'অক্ষিগোলকের ভিতরের পৃষ্ঠের গোলাপী রঙের ঈষদচ্ছ আলোক সংবেদন আবরণটির নাম কি?', 'mcq', '{"ক":"শ্বেত মণ্ডল","খ":"কৃ ষ্ণ মণ্ডল","গ":"আইরিস","ঘ":"রেটিনা"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-016', 'class9-physics-bn-guide', 'satt-physics-board.pdf p194', 'পানির সাপেক্ষে বায়ুর প্রতিসরাংক 0.75 এবং বায়ুতে আলোর বেগ 3 x 108ms-1 হলে পানিতে আলোর বেগ কত?', 'mcq', '{"ক":"4. 43 × 10 ms 9 −1","খ":"2. 50 × 10 ms 9 −1","গ":"3. 99 × 10 ms 8 −1","ঘ":"2. 25 × 10 ms 8 −1"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
