  ('physics-board-cumilla-2019-mcq-019', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', '15 m দীর্ঘ এবং 2.07 x 10-7 m2 প্রস্থচ্ছেদের ক্ষেত্রফলের একটি তারের রোধ 75Ω হলে তারাটির- i. উপাদানের আপেক্ষিক রোধ 1.035 x 106 -m Ω ii. উপাদানের পরিবাহকত্ব 9.66 × 105( -m )-1 Ω iii. রোধ দ্বিগুণ হবে যদি এটি টেনে দৈর্ঘ্য দ্বিগুণ করা হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-020', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'বলের সংজ্ঞা পাওয়া যায় নিউটনের কোন সূত্র থেকে?', 'mcq', '{"ক":"প্রথম গতিসূত্র","খ":"দ্বিতীয় গতিসূত্র","গ":"তৃ তীয় গতিসূত্র","ঘ":"মহাকর্ষ সূত্র"}'::jsonb, 'ক', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'কয়লা চালিত তাপ বিদ্যুৎ কেন্দ্র থেকে কোন ধরনের ধোঁয়া নির্গত হয়?', 'mcq', '{"ক":"কার্বন","খ":"ফসফরাস","গ":"সালফার","ঘ":"থোরিয়াম"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-022', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'ভরবেগের মাত্রা কোনটি?', 'mcq', '{"ক":"M LT −1","খ":"M LT −2","গ":"M L T 2 −2","ঘ":"M L T 2 −3"}'::jsonb, 'ক', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-023', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'এক ব্যক্তি দর্পণের সামনে দাঁড়িয়ে নিজ দৈর্ঘ্যের চেয়ে দ্বিগুণ দৈর্ঘ্যের প্রতিবিম্ব দেখতে পান। বিশ্বের রৈখিক বিবর্ধনের মান কত?', 'mcq', '{"ক":"0.5","খ":"1","গ":"2","ঘ":"4"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, null, 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'ভূ মি থেকে 20 cm উচ্চতায় প্রথম বস্তুটির বিভব শক্তি কত ?', 'mcq', '{"ক":"294000 J","খ":"2940 J","গ":"294 J","ঘ":"2.94 J"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, '1500 gm ও 2000 gm ভরবিশিষ্ট দুইটি বস্তু 20 m উঁচু ছাদ থেকে নিচে পড়ল ।', 'cumilla', 2019, true),
  ('physics-board-cumilla-2019-mcq-025', 'class9-physics-bn-guide', 'satt-physics-board.pdf p195', 'পড়ন্ত বস্তু দুইটির ক্ষেত্রে নিম্নের কোন ঘটনাটি সঠিক?', 'mcq', '{"ক":"সর্বোচ্চ উচ্চতায় বিভব শক্তি একই","খ":"ভূ সম্পর্কে মুহূর্তে বেগ ভিন্ন","গ":"ভূ স্পর্শ করতে ভিন্ন সময় লাগবে","ঘ":"ভূ স্পর্শের মুহূর্তে গতিশক্তি ভিন্ন"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2019-mcq', false, 'board-mcq', null, '1500 gm ও 2000 gm ভরবিশিষ্ট দুইটি বস্তু 20 m উঁচু ছাদ থেকে নিচে পড়ল ।', 'cumilla', 2019, true),
  ('physics-board-cumilla-2020-mcq-001', 'class9-physics-bn-guide', 'satt-physics-board.pdf p146', 'P অবস্থানে বস্তুটির বিভবশক্তি কত?', 'mcq', '{"ক":"588 J","খ":"784 J","গ":"980 J","ঘ":"1176 J"}'::jsonb, 'ঘ', 1, false, 'physics-board-cumilla-2020-mcq', false, 'board-mcq', null, null, 'cumilla', 2020, true),
  ('physics-board-cumilla-2020-mcq-002', 'class9-physics-bn-guide', 'satt-physics-board.pdf p147', 'উক্ত চিত্রের ক্ষেত্রে- i Q বিন্দুতে, গতিশক্তি – বিভবশক্তি = 0 ii. P বিন্দুতে বিভবশক্তি = 6 × R বিন্দুতে বিভবশক্তি iii. PR অংশে গতিশক্তির পরিবর্তন < RS অংশে গতিশক্তির পরিবর্তন নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-cumilla-2020-mcq', false, 'board-mcq', null, null, 'cumilla', 2020, true),
  ('physics-board-cumilla-2020-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p147', 'নিচের কোন পরীক্ষণটিতে টমোগ্রাফির ব্যবহার হয়?', 'mcq', '{"ক":"CT Scan","খ":"ECG","গ":"MRI","ঘ":"এনজিওগ্রাফি"}'::jsonb, 'ক', 1, false, 'physics-board-cumilla-2020-mcq', false, 'board-mcq', null, null, 'cumilla', 2020, true),
