  ('physics-board-cumilla-2020-mcq-005', 'class9-physics-bn-guide', 'satt-physics-board.pdf p147', 'সমআয়তনের বস্তু তিনটিকে উক্ত তরলে ছেড়ে দিলে তাদের অবস্থান চিত্রে দেখানো হলো। A বস্তুটির 60% তরলে নিমজ্জিত অবস্থায় আছে। A বস্তুর ঘনত্ব 600 kg m-3 চিত্রের বস্তুগুলোর ক্ষেত্রে- i. A বস্তুর ভর > A বস্তু কর্তৃক অপসারিত পানির ভর ii. B ও C বস্তুর হারানো ওজন সমান iii. B বস্তুর ঘনত্ব 1000 kg m-1 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-cumilla-2020-mcq', false, 'board-mcq', null, null, 'cumilla', 2020, true),
